mapper.select:
SELECT id, param_name, remark, create_time, update_time
FROM global_param
WHERE id = #{id}

SELECT id, param_name, remark, create_time, update_time
FROM global_param
WHERE param_name = #{paramName}

mapper.update:
UPDATE global_param
SET param_name = #{paramName},
    remark = #{remark}
WHERE id = #{id}

mapper.select:
SELECT t.id, t.param_name, t.remark, t.create_time, t.update_time FROM global_param t INNER JOIN ( SELECT param_name, MIN(id) AS min_id FROM global_param WHERE param_name IN
#{name}
GROUP BY param_name ) g ON t.id = g.min_id
